import sys
data = sys.stdin.read().split()
if data:
    n = int(data[0])
    tokens = data[1:1+n]
    if not tokens or tokens[0] == 'null': sys.exit(0)
    class Node:
        def __init__(self, v): self.v = v; self.left = None; self.right = None
    from collections import deque
    root = Node(tokens[0])
    q = deque([root])
    idx = 1
    while q and idx < len(tokens):
        curr = q.popleft()
        if idx < len(tokens) and tokens[idx] != 'null':
            curr.left = Node(tokens[idx]); q.append(curr.left)
        idx += 1
        if idx < len(tokens) and tokens[idx] != 'null':
            curr.right = Node(tokens[idx]); q.append(curr.right)
        idx += 1
    q = deque([root])
    while q:
        level = []
        for _ in range(len(q)):
            node = q.popleft()
            level.append(str(node.v))
            if node.left: q.append(node.left)
            if node.right: q.append(node.right)
        print(' '.join(level))
